			and Dict_time between #{dictTime} and #{dictTime1}

SELECT a.birth_date AS birthDate,a.user_code AS usercode,a.user_name AS username,a.name, CASE WHEN a.gender = 1 THEN '男' ELSE '女' END AS sex, c.analyzename AS analyzename,c.assess_scores AS assessScores,c.result AS result,c.Dict_time AS dictTime FROM yh_user_reginfo AS a INNER JOIN yh_user_make_card AS b ON a.user_code=b.user_code INNER JOIN yh_life_habit_improvement_dict AS c ON a.user_code=c.user_code where b.doctor=(SELECT id FROM yh_user_admin_info WHERE user_code=#{userCode,jdbcType=VARCHAR})
and c.result=#{result}
and a.name LIKE CONCAT('%',#{name},'%')
and a.user_name LIKE CONCAT('%',#{userName},'%')
and c.Dict_time between #{dictTime} and #{dictTime1}
order by c.Dict_time desc LIMIT #{page},#{limit}

SELECT Count(*) FROM yh_user_reginfo AS a INNER JOIN yh_user_make_card AS b ON a.user_code=b.user_code INNER JOIN yh_life_habit_improvement_dict AS c ON a.user_code=c.user_code where b.doctor=(SELECT id FROM yh_user_admin_info WHERE user_code=#{userCode,jdbcType=VARCHAR})
and c.result=#{result}
and a.name LIKE CONCAT('%',#{name},'%')
and a.user_name LIKE CONCAT('%',#{userName},'%')
and c.Dict_time between #{dictTime} and #{dictTime1}

select * from (select * from (SELECT a.birth_date AS birthDate,a.user_code AS usercode,a.user_name AS username,a.name, CASE WHEN a.gender = 1 THEN '男' ELSE '女' END AS sex, c.analyzename AS analyzename,c.assess_scores AS assessScores,c.result AS result,c.Dict_time AS dictTime,b.Org_Id as orgCode FROM yh_user_reginfo AS a INNER JOIN yh_user_make_card AS b ON a.user_code=b.user_code INNER JOIN yh_life_habit_improvement_dict AS c ON a.user_code=c.user_code where b.doctor=(SELECT id FROM yh_user_admin_info WHERE user_code=#{userCode,jdbcType=VARCHAR}) order by dictTime desc) w group by usercode order by dictTime desc)d
and d.result=#{result}
and d.name LIKE CONCAT('%',#{name},'%')
and d.orgcode LIKE CONCAT('%',#{orgCode},'%')
LIMIT #{page},#{limit}

