  risk, assess_scores, question_id, 
  analyzename, result, Dict_time
  )
values (#{id,jdbcType=INTEGER}, #{title,jdbcType=VARCHAR}, #{userCode,jdbcType=VARCHAR}, 
  #{risk,jdbcType=VARCHAR}, #{assessScores,jdbcType=INTEGER}, #{questionId,jdbcType=INTEGER}, 
  #{analyzename,jdbcType=VARCHAR}, #{result,jdbcType=VARCHAR}, #{dictTime,jdbcType=TIMESTAMP}
  )
